-card h1 em,.intro h2 em,.mission-complete h2 em{font-style:normal;color:#e4c47f}.rule{height:1px;background:linear-gradient(90deg,rgba(232,208,156,.72),transparent);width:218px;margin-bottom:17px}.objective-label{font-size:8px;letter-spacing:1.75px;color:rgba(255,255,255,.58);margin-bottom:10px}.objective{display:flex;align-items:center;gap:10px;font-size:11px;font-weight:600}.objective-check{width:24px;height:24px;border:1px solid rgba(234,204,145,.65);color:#e8c77f;display:grid;place-items:center;font:600 10px 'Barlow Condensed'}.target-readout{margin-top:19px;width:220px;border-top:1px solid rgba(255,255,255,.22);padding-top:12px;display:flex;align-items:center;gap:7px;font-size:8px;letter-spacing:1px;color:rgba(255,255,255,.68)}.target-readout b{margin-left:auto;font-size:10px;color:#fff;letter-spacing:1px}.pulse-dot{width:5px;height:5px;border-radius:50%;background:#e67654;box-shadow:0 0 8px #f06e53;animation:pulse 1.8s infinite}@keyframes pulse{50%{opacity:.35;box-shadow:0 0 2px #f06e53}}.top-center{top:26px;left:50%;transform:translateX(-50%)}.compass{width:245px;height:30px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,.3);position:relative;color:rgba(255,255,255,.72);font:500 10px 'Barlow Condensed';letter-spacing:2px}.compass:before,.compass:after{content:'';position:absolute;bottom:-4px;width:1px;height:8px;background:rgba(255,255,255,.45)}.compass:before{left:0}.compass:after{right:0}.compass-main{color:white;font-weight:700;font-size:12px}.compass-main small{color:#e4c47f}.compass-mark{height:5px;width:1px;background:rgba(255,255,255,.6)}.status-card{top:100px;right:40px;width:204px;padding:13px 15px 11px;background:rgba(16,28,29,.46);border:1px solid rgba(255,255,255,.2);backdrop-filter:blur(8px)}.status-head{display:flex;justify-content:space-between;font-size:8px;letter-spacing:1.5px;font-weight:700;color:rgba(255,255,255,.78);margin-bottom:13px}.status-ready{color:#b4d0b1}.stat-row{display:fl