spacing:1.4px;color:rgba(255,255,255,.65)}.controls{left:0;right:0;bottom:0;padding:0 40px 24px;display:flex;justify-content:center;pointer-events:none}.control-hint{background:rgba(17,29,30,.55);border:1px solid rgba(255,255,255,.2);padding:11px 17px;font-size:8px;letter-spacing:1.4px;color:rgba(255,255,255,.8);backdrop-filter:blur(8px)}.keycap{font:600 10px 'Barlow Condensed';color:#f3d899;border:1px solid rgba(243,216,153,.48);padding:3px 5px;margin-right:5px}.hint-divider{color:#d7b978;margin:0 8px}.mobile-pad{display:none}.speed-lines{position:absolute;inset:0;z-index:2;pointer-events:none;opacity:0;background:repeating-linear-gradient(105deg,transparent 0 17%,rgba(255,255,255,.12) 17.1%,transparent 17.3% 29%);mix-blend-mode:screen;transition:opacity .2s}.speed-lines.active{opacity:.27}.intro{position:absolute;z-index:5;inset:0;display:flex;flex-direction:column;justify-content:space-between;padding:112px 10vw 40px;background:linear-gradient(90deg,rgba(15,27,28,.76),rgba(15,27,28,.48) 42%,rgba(15,27,28,.02) 80%),linear-gradient(0deg,rgba(10,19,21,.58),transparent 53%);transition:opacity .55s,visibility .55s}.intro.hidden{opacity:0;visibility:hidden;pointer-events:none}.intro-top{max-width:340px}.intro-top .eyebrow{font-size:9px;display:flex;align-items:center;gap:10px}.intro-rule{width:140px;height:1px;margin-top:15px;background:linear-gradient(90deg,#dfbb76,transparent)}.intro-content{margin-top:auto;margin-bottom:auto;max-width:540px;padding-top:28px}.chapter{font-size:9px;letter-spacing:2px;color:rgba(255,255,255,.69);margin-bottom:17px}.chapter b{color:#e6c482}.chapter span{padding:0 7px;color:rgba(255,255,255,.42)}.intro h2,.mission-complete h2{font:800 clamp(66px,8.5vw,116px)/.77 'Barlow Condensed',sans-serif;letter-spacing:1px;margin:0;text-shadow:0 4px 20px rgba(10,16,19,.4)}.intro-content>p{font-size:12px;line-height:1.75;max-width:340px;color:rgba(255,255,255,.77);margin:24px 0 28px}.launch-row{display:flex;align-items:center;gap:17px}.launch-button{pointer-events:auto;border:0;background:#dfbd7b;color:#1c2929;padding:14px 19px;font-size:9px;font-weight:700;letter-spacing:1.3px;cursor:pointer;min-width:195px;display:flex;align-items:center;justify-content:space-between;gap:18px;transition:background .2s,transform .2s}.launch-button:hover{background:#efd59e;transform:translateY(-2px)}.launch-button span{font-size:16px}.launch-meta{display:grid;gap:5px;font-size:7px;letter-spacing:1.2px;color:rgba(255,255,255,.53)}.launch-meta b{font-weight:500;color:rgba(255,255,255,.84)}.intro-bottom{display:flex;justify-content:space-between;font-size:8px;letter-spacing:1.8px;color:rgba(255,255,255,.56);border-top:1px solid rgba(255,255,255,.23);padding-top:14px}.intro-bottom b{color:#e1c17d;margin-left:6px}.loading{position:absolute;z-index:8;inset:0;display:flex;align-items:center;justify-content:center;gap:13px;background:#263739;color:#f1e8d4;font-size:9px;letter-spacing:2px;transition:opacity .4s,visibility .4s}.loading.done{opacity:0;visibility:hidden}.loading-mark{font:700 20px 'Barlow Condensed';color:#e1c17d}.loading i{position:absolute;bottom:0;left:0;width:100%;height:2px;background:#dfbd7b;transform-origin:left;animation:load 1s ease-out forwards}@keyframes load{to{transform:scaleX(1)}}.mission-complete{position:absolute;z-index:6;inset:0;display:none;align-items:center;justify-content:center;flex-direction:column;text-align:center;background:rgba(12,22,23,.8);backdrop-filter:blur(8px)}.mission-complete.visible{display:flex}.complete-seal{font-size:29px;color:#e4c47f;margin-bottom:20px}.mission-complete h2{font-size:72px;margin:13px 0}.mission-complete p{font-size:12px;color:rgba(255,255,255,.7);margin:10px}.final-score{font-size:8px;letter-spacing:2px;color:#e4c47f;margin:18px 0 22px}.mission-complete .launch-button{justify-content:center}
