lex-end;gap:7px;padding-bottom:5px;pointer-events:auto}.action-button{width:52px;height:57px;border-radius:28px 28px 22px 22px;background:rgba(16,27,29,.58);border:1px solid rgba(255,255,255,.4);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1px;touch-action:none;box-shadow:0 4px 14px rgba(0,0,0,.18)}.action-button:active,.action-button.pressed{background:rgba(218,184,117,.75);color:#182526;transform:scale(.94)}.action-icon{font-size:20px;line-height:22px}.action-button small{font-size:6px;letter-spacing:1px;font-weight:700}.attack-button{width:59px;height:65px;border-color:rgba(232,192,117,.8);background:rgba(91,56,41,.63)}.attack-button .action-icon{font-size:23px}.boost-button{width:46px;height:51px}.intro{padding:82px 22px 19px;background:linear-gradient(90deg,rgba(15,27,28,.7),rgba(15,27,28,.2)),linear-gradient(0deg,rgba(10,19,21,.7),transparent 70%)}.intro-top .eyebrow{font-size:7px}.intro-rule{margin-top:10px}.intro-content{padding-top:0;max-width:100%}.chapter{font-size:7px;letter-spacing:1.5px;margin-bottom:13px}.intro h2{font-size:clamp(64px,17vw,98px)}.intro-content>p{font-size:11px;max-width:285px;margin:19px 0 21px;line-height:1.7}.launch-row{align-items:flex-start;flex-direction:column;gap:12px}.launch-button{padding:13px 15px;min-width:196px;font-size:8px}.launch-meta{display:flex;gap:10px;font-size:6px}.intro-bottom{font-size:6px;letter-spacing:1.1px;padding-top:11px}.mission-complete h2{font-size:59px}.toast{top:65%;font-size:7px;white-space:nowrap}}
